const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#0A1D3A",
  transparentBackground = false,
  durationInSeconds = 10,
  doctorCircleColor = "#e3f2fd",
  dentistCircleColor = "#b2dfdb",
  vetCircleColor = "#c8e6c9",
  doctorSkinTone = "#ffccbc",
  dentistSkinTone = "#ffccbc",
  vetSkinTone = "#ffccbc",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Staggered start frames designed for Doctor first, Dentist second, and Vet last
  const docStart = 10;
  const denStart = docStart + 15; // dentist starts 15 frames after doctor
  const vetStart = denStart + 15; // vet starts 15 frames after dentist

  // Entrance springs
  const docPop = spring({ frame: frame - docStart, fps, config: { damping: 12, mass: 0.8 } });
  const denPop = spring({ frame: frame - denStart, fps, config: { damping: 13, mass: 0.8 } });
  const vetPop = spring({ frame: frame - vetStart, fps, config: { damping: 13, mass: 0.8 } });

  // Slow floating logic (deterministically driven by frame and scaled by their entrance progress)
  const denFloatX = denPop * Math.sin(frame * 0.035) * 32 * s;
  const denFloatY = denPop * Math.cos(frame * 0.04) * 32 * s;

  const vetFloatX = vetPop * Math.cos(frame * 0.03 + 2) * 32 * s;
  const vetFloatY = vetPop * Math.sin(frame * 0.035 + 1.5) * 32 * s;

  const docFloatX = docPop * Math.sin(frame * 0.025 - 1) * 24 * s;
  const docFloatY = docPop * Math.cos(frame * 0.03 + 3) * 36 * s;

  // Layout parameters relative to center
  const originX = width / 2;
  const originY = height / 2;
  
  const circleBaseSize = 480 * s;
  const doctorSize = circleBaseSize * 1.15; // Doctor slightly larger in foreground
  const borderWidth = 16 * s;

  // Target Offsets from center (spread out more)
  const docTargetY = 220 * s;
  const sideTargetY = -200 * s;
  const sideTargetX = 300 * s;

  // Render order matters for Z-index: Dentist/Vet first, Doctor last.
  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Dentist (Left) */}
      <AbsoluteFill
        style={{
          width: circleBaseSize,
          height: circleBaseSize,
          borderRadius: "50%",
          backgroundColor: dentistCircleColor,
          border: `${borderWidth}px solid white`,
          overflow: "hidden(),",
          left: originX - circleBaseSize / 2,
          top: originY - circleBaseSize / 2,
          transform: `
            translate(${interpolate(denPop, [0, 1], [0, -sideTargetX]) + denFloatX}px, ${interpolate(denPop, [0, 1], [0, sideTargetY]) + denFloatY}px)
            scale(${denPop})
          `,
          opacity: frame >= denStart ? 1 : 0,
          transition: "none",
        }}
      >
        <DentistAvatar skinTone={dentistSkinTone} />
      </AbsoluteFill>

      {/* Vet (Right) */}
      <AbsoluteFill
        style={{
          width: circleBaseSize,
          height: circleBaseSize,
          borderRadius: "50%",
          backgroundColor: vetCircleColor,
          border: `${borderWidth}px solid white`,
          overflow: "hidden",
          left: originX - circleBaseSize / 2,
          top: originY - circleBaseSize / 2,
          transform: `
            translate(${interpolate(vetPop, [0, 1], [0, sideTargetX]) + vetFloatX}px, ${interpolate(vetPop, [0, 1], [0, sideTargetY]) + vetFloatY}px)
            scale(${vetPop})
          `,
          opacity: frame >= vetStart ? 1 : 0,
          transition: "none",
        }}
      >
        <VetAvatar skinTone={vetSkinTone} />
      </AbsoluteFill>

      {/* Doctor (Center Foreground) */}
      <AbsoluteFill
        style={{
          width: doctorSize,
          height: doctorSize,
          borderRadius: "50%",
          backgroundColor: doctorCircleColor,
          border: `${borderWidth}px solid white`,
          overflow: "hidden",
          left: originX - doctorSize / 2,
          top: originY - doctorSize / 2,
          transform: `
            translate(${docFloatX}px, ${interpolate(docPop, [0, 1], [0, docTargetY]) + docFloatY}px)
            scale(${docPop})
          `,
          opacity: frame >= docStart ? 1 : 0,
          boxShadow: `0 ${20 * s}px ${40 * s}px rgba(0,0,0,0.15)`, // Slight shadow to separate foreground
          transition: "none",
        }}
      >
        <DoctorAvatar skinTone={doctorSkinTone} />
      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default ComponentName;